#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
#pragma omp parallel
    {
#pragma omp single
        max_threads = omp_get_num_threads();
    }

    std::vector<long long> blockSums(max_threads, 0LL);
    std::vector<long long> blockOffsets(max_threads, 0LL);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T = omp_get_num_threads();

        const int start = (tid * n) / T;
        const int end   = ((tid + 1) * n) / T; // [start, end)

        // Local reverse-prefix over this block, written in increasing index order:
        // output[i] = sum_{k=start..i} x[k]
        long long running = 0;
        for (int i = start; i < end; ++i) {
            running += x[i];
            output[i] = static_cast<int>(running);
        }
        blockSums[tid] = running;

#pragma omp barrier

#pragma omp single
        {
            long long acc = 0;
            for (int t = 0; t < T; ++t) {
                blockOffsets[t] = acc;
                acc += blockSums[t];
            }
        }

        const long long offset = blockOffsets[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(output[i] + offset);
        }
    }
}
